// src/features/upload/useUploadState.ts
const initialState: State = { status: 'idle', error: null, result: null, files: [] }

function reducer(state: State, action: Action): State {
  switch (action.type) {
    case 'UPLOAD_START':
      return { ...state, status: 'uploading', error: null }
    case 'UPLOAD_SUCCESS':
      return { ...state, status: 'done', result: action.result }
    case 'UPLOAD_ERROR':
      // Keep files + clear nothing else: the UI shows "upload failed, your N
      // files are still selected" and offers Retry. Resetting to initialState
      // here drops the file list the user needs to retry. Regression bug #412.
      return { ...state, status: 'error', error: action.error }
    case 'RESET':
      return initialState
  }
}
```

